import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getProductionConfig, isFeatureEnabled } from "../_shared/production_config_cache.ts";

import { acceptOrderAtomically } from "./atomic_acceptance.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
);

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", {
      headers: corsHeaders,
    });
  }

  // Hoisted out of the try block (Phase 5 F5: logging-only) so the catch-all error handler below
  // can include them for diagnosis -- no change to any value, validation, or control flow, only to
  // where these two references are declared.
  let order_id: any;
  let rider_id: any;

  try {
    const body = await req.json();
    order_id = body.order_id;
    rider_id = body.rider_id;

    if (!order_id || !rider_id) {
      return Response.json(
        {
          success: false,
          message: "order_id and rider_id required",
        },
        {
          status: 400,
          headers: corsHeaders,
        },
      );
    }

    // =====================================================
    // AUTH
    // =====================================================
    const token = req.headers.get("Authorization")?.replace("Bearer ", "");

    if (!token) {
      return Response.json(
        { success: false, message: "Missing auth token" },
        { status: 401, headers: corsHeaders },
      );
    }

    // Auth resolution and the order fetch are independent of each other's result (order_id was
    // already validated above, before either starts) -- run concurrently instead of serially.
    // Same two checks, same precedence (auth checked first below, exactly as before, so an
    // invalid token still always yields 401 regardless of order_id), same responses either way;
    // only removes one round trip's worth of serial wait per call on this rider-accept hot path.
    const [{ data: authData, error: authError }, { data: order, error: orderError }] =
      await Promise.all([
        supabase.auth.getUser(token),
        supabase.from("orders").select("*").eq("id", order_id).single(),
      ]);

    if (authError || !authData.user) {
      return Response.json(
        { success: false, message: "Unauthorized" },
        { status: 401, headers: corsHeaders },
      );
    }

    // =====================================================
    // FETCH ORDER
    // =====================================================
    if (orderError || !order) {
      return Response.json(
        {
          success: false,
          message: "Order not found",
        },
        {
          status: 404,
          headers: corsHeaders,
        },
      );
    }

    // Idempotent retries still pass server-side ownership/invariant checks.
    // A new acceptance retains the existing feature gates before the RPC.
    if (!(order.rider_id === rider_id && order.order_status === "accepted")) {
      const productionConfig = await getProductionConfig(supabase);
      if (order.order_type === "ride") {
        if (
          !isFeatureEnabled(productionConfig, "local_rides_enabled") ||
          !isFeatureEnabled(productionConfig, "ride_booking_enabled")
        ) {
          return Response.json(
            { success: false, message: "Ride booking is temporarily unavailable. Please try again later." },
            { status: 503, headers: corsHeaders },
          );
        }
      } else if (order.order_type === "local_parcel") {
        if (!isFeatureEnabled(productionConfig, "parcel_enabled")) {
          return Response.json(
            { success: false, message: "Parcel booking is temporarily unavailable. Please try again later." },
            { status: 503, headers: corsHeaders },
          );
        }
      } else if (order.order_type === "intercity_ride" || order.order_type === "intercity_parcel") {
        if (!isFeatureEnabled(productionConfig, "intercity_enabled")) {
          return Response.json(
            { success: false, message: "Intercity booking is temporarily unavailable. Please try again later." },
            { status: 503, headers: corsHeaders },
          );
        }
      }
    }

    // The transaction runs inside this Edge Function. No RPC/schema migration is required.
    let acceptance;
    try {
      acceptance = await acceptOrderAtomically(order_id, rider_id, authData.user.id);
    } catch (error) {
      const code = (error as { code?: string }).code;
      const retryable = ["40001", "40P01", "55P03", "57014", "53300", "08006", "CONNECTION_CLOSED", "CONNECT_TIMEOUT", "ECONNRESET"].includes(code ?? "");
      console.error("accept-order transaction failed", { order_id, rider_id, code });
      return Response.json(
        { success: false, message: retryable ? "Acceptance is busy. Please retry." : "Unable to accept order", retryable },
        { status: retryable ? 503 : 500, headers: corsHeaders },
      );
    }
    const { http_status, ...responseBody } = acceptance;
    return Response.json(responseBody, { status: http_status, headers: corsHeaders });
  } catch (error) {
    console.error("ACCEPT ORDER ERROR:", { order_id, rider_id, error });
    // A malformed request body (req.json() throwing) is a client mistake, not a server failure --
    // was previously indistinguishable from a genuine crash once it fell into this catch-all 500.
    if (error instanceof SyntaxError) {
      return Response.json(
        { success: false, message: "Malformed request body" },
        { status: 400, headers: corsHeaders },
      );
    }
    return Response.json(
      {
        success: false,
        message: "Internal server error",
      },
      {
        status: 500,
        headers: corsHeaders,
      },
    );
  }
});

import postgres from 'npm:postgres@3.4.5';
import { ACCEPTANCE_SQL } from './acceptance_sql.ts';

export type AcceptanceResult = { http_status: number; success: boolean; [key: string]: unknown };

// Exported factory permits independent native connections in concurrency tests.
export function createAcceptanceExecutor(databaseUrl: string, projectUrl: string) {
  const db = new URL(databaseUrl);
  const project = new URL(projectUrl);
  const local = ['127.0.0.1', 'localhost'].includes(db.hostname) &&
    ['127.0.0.1', 'localhost'].includes(project.hostname) &&
    db.port === '54329' && db.pathname === '/waydrop_perf_test';
  if (!['postgres:', 'postgresql:'].includes(db.protocol) ||
    (!local && (project.protocol !== 'https:' || !project.hostname.endsWith('.supabase.co') ||
      db.hostname !== 'db.' + project.hostname || (db.port && db.port !== '5432')))) {
    throw new Error('Unsupported direct database endpoint');
  }
  // One connection per warm isolate; no prepared statements or pipelined arrays.
  // Production TLS verification is never disabled. Missing CA/connectivity fails closed.
  const sql = postgres(databaseUrl, {
    max: 1, prepare: false, connect_timeout: 5, idle_timeout: 10, max_lifetime: 60,
    ssl: local ? false : { rejectUnauthorized: true },
    connection: { application_name: 'waydrop_accept_order_atomic' },
  });
  return {
    async accept(orderId: string, riderId: string, actorId: string): Promise<AcceptanceResult> {
      return await sql.begin('isolation level read committed', async (tx) => {
        await tx`SET LOCAL ROLE service_role`;
        await tx`SELECT set_config('request.jwt.claim.role','service_role',true),
          set_config('request.jwt.claims','{"role":"service_role"}',true),
          set_config('request.jwt.claim.sub','',true),set_config('request.jwt.claim.email','',true),
          set_config('search_path','pg_catalog,public',true),set_config('lock_timeout','3s',true),set_config('statement_timeout','10s',true),
          set_config('app.accept_order_id',${orderId},true),
          set_config('app.accept_rider_id',${riderId},true),
          set_config('app.accept_actor_id',${actorId},true),
          set_config('app.acceptance_result','',true)`;
        await tx.unsafe(ACCEPTANCE_SQL);
        const [row] = await tx<{ result: AcceptanceResult }[]>`
          SELECT current_setting('app.acceptance_result')::jsonb AS result`;
        if (!row?.result?.http_status) throw new Error('Acceptance result missing');
        return row.result;
      }); // Resolves only after successful COMMIT; rejects on any statement/commit failure.
    },
    async close() { await sql.end({ timeout: 3 }); },
  };
}

let executor: ReturnType<typeof createAcceptanceExecutor> | undefined;
export async function acceptOrderAtomically(orderId: string, riderId: string, actorId: string) {
  if (!executor) {
    const url = Deno.env.get('SUPABASE_DB_URL');
    if (!url) throw new Error('Database connection unavailable');
    executor = createAcceptanceExecutor(url, Deno.env.get('SUPABASE_URL')!);
  }
  return await executor.accept(orderId, riderId, actorId);
}

export async function closeAcceptanceExecutor() { const current = executor; executor = undefined; if (current) await current.close(); }

// Anonymous PL/pgSQL block. Executed only inside one direct DB transaction.
export const ACCEPTANCE_SQL = "DO $acceptance$
DECLARE
  p_order_id uuid:=nullif(current_setting('app.accept_order_id',true),'')::uuid;
  p_rider_id uuid:=nullif(current_setting('app.accept_rider_id',true),'')::uuid;
  p_actor_user_id uuid:=nullif(current_setting('app.accept_actor_id',true),'')::uuid;
  v_order public.orders%ROWTYPE;
  v_rider public.riders%ROWTYPE;
  v_assignment public.rider_assignments%ROWTYPE;
  v_required_mode public.partner_service_mode_enum;
  v_breakdown jsonb;
  v_subscription boolean;
  v_estimated_earnings numeric;
  v_now timestamptz:=now();
BEGIN
  -- Only the authenticated Edge service client may call this RPC. The actor
  -- comes from getUser(token), never from the request body. No client grants.
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service-role caller required' USING ERRCODE='42501';
  END IF;
  -- PostgREST uses READ COMMITTED. A caller with a pinned older snapshot could
  -- miss another order accepted while waiting for the rider lock. Fail closed
  -- instead of allowing that REPEATABLE READ write-skew case.
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION 'Acceptance requires READ COMMITTED isolation' USING ERRCODE='40001';
  END IF;
  IF p_order_id IS NULL OR p_rider_id IS NULL OR p_actor_user_id IS NULL THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',400,'success',false,'message','Order, rider and authenticated actor are required'))::text,true); RETURN;
  END IF;

  -- Rider first serializes simultaneous accepts of DIFFERENT orders by one
  -- rider. The subsequent order lock serializes DIFFERENT riders for one order.
  SELECT * INTO v_rider FROM public.riders WHERE id=p_rider_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',404,'success',false,'message','Rider not found'))::text,true); RETURN;
  END IF;
  IF v_rider.user_id IS DISTINCT FROM p_actor_user_id THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',403,'success',false,'message','Forbidden: rider_id does not belong to authenticated user'))::text,true); RETURN;
  END IF;
  SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',404,'success',false,'message','Order not found'))::text,true); RETURN;
  END IF;

  -- Idempotent retry reads committed state; no timestamps, fares, logs or
  -- notifications are rewritten. Ownership was checked before this branch.
  IF v_order.order_status='accepted' AND v_order.rider_id=p_rider_id THEN
    SELECT * INTO v_assignment FROM public.rider_assignments
    WHERE order_id=p_order_id AND rider_id=p_rider_id AND assignment_status='accepted';
    IF NOT FOUND OR (SELECT count(*) FROM public.rider_assignments WHERE order_id=p_order_id AND assignment_status='accepted')<>1 THEN
      PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',409,'success',false,'code','ACCEPTANCE_STATE_INCONSISTENT','message','Accepted order has no matching accepted assignment'))::text,true); RETURN;
    END IF;
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',200,'success',true,'idempotent',true,
      'message','Order already accepted by this rider','order',to_jsonb(v_order),'assignment',to_jsonb(v_assignment)))::text,true); RETURN;
  END IF;
  IF v_order.order_status<>'searching' THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',409,'success',false,
      'message',CASE WHEN v_order.order_status='accepted' THEN 'Order already accepted by another rider' ELSE 'Order no longer available' END,
      'current_status',v_order.order_status))::text,true); RETURN;
  END IF;

  IF EXISTS (SELECT 1 FROM public.rider_assignments WHERE order_id=p_order_id AND assignment_status='accepted') THEN
    PERFORM set_config('app.acceptance_result',jsonb_build_object('http_status',409,'success',false,'code','ACCEPTANCE_STATE_INCONSISTENT','message','Order acceptance state requires review')::text,true); RETURN;
  END IF;
  -- Re-read and validate eligibility under the locks. Existing rules retained.
  v_required_mode:=public.get_required_service_mode(v_order.order_type::text,v_order.distance_meters);
  IF v_rider.service_mode IS DISTINCT FROM v_required_mode THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',403,'success',false,'code','WRONG_SERVICE_MODE',
      'message',CASE WHEN v_rider.service_mode IS NULL THEN 'Choose a Service Mode in your Profile before accepting orders.'
        WHEN v_required_mode='local' THEN 'Switch to Local Rides mode to accept this order.' ELSE 'Switch to Intercity Traveller mode to accept this order.' END))::text,true); RETURN;
  END IF;
  IF v_rider.user_id=v_order.user_id THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',400,'success',false,'message','You cannot accept your own order'))::text,true); RETURN;
  END IF;
  IF v_rider.account_status IS DISTINCT FROM 'online' THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',400,'success',false,'message','Rider not online'))::text,true); RETURN;
  END IF;
  IF public.is_rider_blocked_by_tax_due(p_rider_id) THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',403,'success',false,'code','TAX_DUE_THRESHOLD_BLOCKED',
      'message','New orders are paused because your Government Tax Due has reached the limit. Pay the due amount to continue receiving orders.'))::text,true); RETURN;
  END IF;
  IF public.is_rider_blocked_by_cod_limit(p_rider_id) THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',403,'success',false,'code','COD_LIMIT_EXCEEDED',
      'message','You''ve reached your cash collection limit. Please settle your pending cash amount to resume receiving orders.'))::text,true); RETURN;
  END IF;
  IF public.rider_is_on_active_trip(p_rider_id) THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',400,'success',false,'message','Rider already has an active order'))::text,true); RETURN;
  END IF;

  SELECT * INTO v_assignment FROM public.rider_assignments
  WHERE order_id=p_order_id AND rider_id=p_rider_id FOR UPDATE;
  IF FOUND AND v_assignment.assignment_status NOT IN ('sent','accepted_by_user','rejected','expired') THEN
    PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',400,'success',false,'message','Assignment already handled',
      'assignment_status',v_assignment.assignment_status))::text,true); RETURN;
  END IF;

  -- Use the SAME canonical function and locked order rates. Preserve the
  -- passenger total and existing promo discount; no formula is duplicated.
  v_estimated_earnings:=v_order.rider_earning;
  v_subscription:=COALESCE(v_rider.subscription_active AND v_rider.subscription_expires_at>v_now,false);
  v_breakdown:=public.calculate_fare_breakdown(
    v_order.current_fare,v_order.actual_fare,COALESCE(v_order.gst_percentage,5),
    CASE WHEN v_subscription THEN 0 ELSE COALESCE(v_order.commission_percentage,10) END,
    GREATEST(0,v_order.current_fare-COALESCE(v_order.final_fare,v_order.current_fare)));
  IF v_breakdown IS NULL THEN
    RAISE EXCEPTION 'Failed to calculate fare breakdown';
  END IF;

  -- Every write below belongs to this single RPC transaction. Any constraint,
  -- trigger, assignment, log, timeout or commit failure aborts all its writes.
  UPDATE public.orders SET order_status='accepted',rider_id=p_rider_id,
    accepted_at=v_now,updated_at=v_now,
    current_fare=(v_breakdown->>'current_fare')::numeric,
    final_fare=(v_breakdown->>'final_fare')::numeric,
    commission_amount=(v_breakdown->>'commission_amount')::numeric,
    gst_amount=(v_breakdown->>'gst_amount')::numeric,
    rider_earning=(v_breakdown->>'rider_earning')::numeric,
    subscription_commission_waived=v_subscription
  WHERE id=p_order_id RETURNING * INTO v_order;

  UPDATE public.rider_assignments SET assignment_status='expired',updated_at=v_now,
    response_type='ignored',last_response_at=v_now
  WHERE order_id=p_order_id AND rider_id<>p_rider_id AND assignment_status='sent';
  UPDATE public.order_assignment_logs SET assignment_status='expired',responded_at=v_now
  WHERE order_id=p_order_id AND rider_id<>p_rider_id AND assignment_status='sent';

  IF v_assignment.id IS NULL THEN
    INSERT INTO public.rider_assignments AS ra(order_id,rider_id,assignment_round,assignment_status,
      sent_at,responded_at,accepted_at,updated_at,response_type,last_response_at,estimated_earnings,
      expires_at)
    VALUES(p_order_id,p_rider_id,1,'accepted',v_now,v_now,v_now,v_now,'accepted',v_now,v_estimated_earnings,
      v_now+(COALESCE((SELECT rider_response_timeout_sec FROM public.dispatch_config WHERE is_active=true LIMIT 1),25)||' seconds')::interval)
    ON CONFLICT(order_id,rider_id) DO UPDATE SET assignment_status='accepted',
      responded_at=EXCLUDED.responded_at,updated_at=EXCLUDED.updated_at,
      response_type='accepted',last_response_at=EXCLUDED.last_response_at
    WHERE ra.assignment_status IN ('sent','accepted_by_user','rejected','expired')
    RETURNING * INTO v_assignment;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Assignment changed during acceptance; retry' USING ERRCODE='40001';
    END IF;
  ELSE
    UPDATE public.rider_assignments SET assignment_status='accepted',responded_at=v_now,
      updated_at=v_now,response_type='accepted',last_response_at=v_now
    WHERE id=v_assignment.id RETURNING * INTO v_assignment;
  END IF;
  UPDATE public.order_assignment_logs SET assignment_status='accepted',responded_at=v_now
  WHERE order_id=p_order_id AND rider_id=p_rider_id;
  IF NOT FOUND THEN
    INSERT INTO public.order_assignment_logs(order_id,rider_id,assignment_round,assignment_status,sent_at,responded_at)
    VALUES(p_order_id,p_rider_id,1,'accepted',v_now,v_now);
  END IF;
  IF (SELECT count(*) FROM public.rider_assignments WHERE order_id=p_order_id AND assignment_status='accepted')<>1 OR NOT EXISTS (SELECT 1 FROM public.rider_assignments
                 WHERE order_id=p_order_id AND rider_id=p_rider_id AND assignment_status='accepted') THEN
    RAISE EXCEPTION 'Accepted assignment was not retained; retry' USING ERRCODE='40001';
  END IF;
  PERFORM set_config('app.acceptance_result',(jsonb_build_object('http_status',200,'success',true,'order',to_jsonb(v_order),'assignment',to_jsonb(v_assignment)))::text,true); RETURN;
END;
$acceptance$;";

// Shared helper: getProductionConfig / isFeatureEnabled
//
// In-memory TTL cache for the single active `production_config` row, scoped to this Deno isolate --
// same pattern as getDispatchConfig (dispatch_config_cache.ts): Supabase Edge Function isolates are
// reused across nearby-in-time invocations, so a short module-scope TTL cache avoids re-querying a
// 1-row table on every single request while never risking config staler than the TTL.
//
// This is the server-side half of the Phase 1 production control system. The Flutter client enforces
// feature flags for UI visibility (see FeatureFlags/ProductionConfigService); this file is what the
// safest, most central Edge Functions (create-order, create-payment, send-push-notification) check
// before actually performing the operation a flag controls, so a flag is never "just a UI toggle".

// deno-lint-ignore no-explicit-any
type ProductionConfig = Record<string, any>;

const TTL_MS = 30_000;

let cached: ProductionConfig | null = null;
let cachedAt = 0;
let inFlight: Promise<ProductionConfig | null> | null = null;

/**
 * Returns the active production_config row, refetching via `supabase` only if the cache is empty or
 * older than 30s. Concurrent invocations that land in this isolate during a refresh share the same
 * in-flight request instead of each firing their own duplicate query.
 *
 * Returns null if the row cannot be fetched (e.g. transient DB error) -- callers must treat a null
 * config as "no restriction" (fail open), never as "everything disabled", so a config outage cannot
 * itself take down ride booking / payments / notifications. This mirrors the Flutter client's own
 * documented fail-open policy for the same reason.
 */
export async function getProductionConfig(
  // deno-lint-ignore no-explicit-any
  supabase: any,
): Promise<ProductionConfig | null> {
  const now = Date.now();
  if (cached && now - cachedAt < TTL_MS) {
    return cached;
  }
  if (inFlight) {
    return inFlight;
  }

  inFlight = (async () => {
    try {
      const { data } = await supabase
        .from("production_config")
        .select("*")
        .eq("is_active", true)
        .single();
      cached = data ?? null;
      cachedAt = Date.now();
      return cached;
    } catch (_e) {
      // Fail open: keep serving the previous cached value (even if stale) rather than treating a
      // transient fetch error as "config says disabled".
      return cached;
    }
  })();

  try {
    return await inFlight;
  } finally {
    inFlight = null;
  }
}

/**
 * Reads a named boolean flag off a (possibly null) config row, defaulting to `true` (enabled) when
 * the config is unavailable or the column is missing/null -- never fail closed on a config outage.
 */
export function isFeatureEnabled(
  config: ProductionConfig | null,
  key: string,
  defaultValue = true,
): boolean {
  if (!config) return defaultValue;
  const value = config[key];
  return typeof value === "boolean" ? value : defaultValue;
}
